func ComputeBackoffMs(baseMs int64, maxMs int64, attempt int) int64 {
	if attempt < 1 {
		attempt = 1
	}
	if attempt > 30 {
		return maxMs
	}
	delay := baseMs << (attempt - 1)
	if delay > maxMs || delay <= 0 {
		return maxMs
	}
	return delay
}

